const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const supportedRegions = ["United States", "Alabama", "Alaska", "Arizona", "Arkansas", "California", "Colorado", "Connecticut", "Delaware", "Florida", "Georgia", "Hawaii", "Idaho", "Illinois", "Indiana", "Iowa", "Kansas", "Kentucky", "Louisiana", "Maine", "Maryland", "Massachusetts", "Michigan", "Minnesota", "Mississippi", "Missouri", "Montana", "Nebraska", "Nevada", "New Hampshire", "New Jersey", "New Mexico", "New York", "North Carolina", "North Dakota", "Ohio", "Oklahoma", "Oregon", "Pennsylvania", "Rhode Island", "South Carolina", "South Dakota", "Tennessee", "Texas", "Utah", "Vermont", "Virginia", "Washington", "West Virginia", "Wisconsin", "Wyoming"];
$$('[data-region-select]').forEach(select => { const regions = select.hasAttribute("data-state-only") ? supportedRegions.slice(1) : supportedRegions; select.innerHTML = regions.map(region => `<option value="${region}">${region}</option>`).join(""); select.value = select.dataset.default || regions[0]; });
const activityProfile = (title, value, metadata) => ({ title, value, unit: "activity level", chartUnit: `Weekly median · standardized ${title.toLowerCase()}`, y: ["12", "9", "6", "3", "0"], metadata, mode: "activity", trend: "↑ 18%", trendNote: "from prior 7 days", coverage: "Coverage: 9 of 12 sites <b>•</b> 2 days old", modeLabel: "Standardized activity monitoring", modeCopy: "Comparable illustrative activity views are available for this pathogen." });
const detectionProfile = (title, value, metadata) => ({ title, value, unit: "reporting sites", chartUnit: "Weekly detection count · illustrative reporting sites", y: ["12", "9", "6", "3", "0"], metadata, mode: "detection", trend: `${value} detections`, trendNote: "in latest reporting week", coverage: "Site-level detection reporting <b>•</b> weekly updates", modeLabel: "Site-level detection monitoring", modeCopy: "Detection status is not equivalent to a standardized state activity level." });
const validationProfile = title => ({ title, value: "—", unit: "coverage pending", chartUnit: "Comparable public state-level coverage not yet enabled", y: ["", "", "", "", ""], metadata: `${title} wastewater monitoring candidate`, mode: "validation", trend: "Validation needed", trendNote: "before state comparisons", coverage: "No comparable public state coverage available", modeLabel: "Coverage validation pending", modeCopy: "This candidate remains unavailable until public coverage and method validation support state-level comparison." });
const pathogenProfiles = {
  "COVID-19": activityProfile("SARS-CoV-2 wastewater activity", "8.4", "SARS-CoV-2 RNA wastewater activity"),
  "Influenza A": activityProfile("Influenza A wastewater activity", "7.1", "Influenza A wastewater activity"),
  "RSV": activityProfile("RSV wastewater activity", "4.8", "RSV wastewater activity"),
  "Measles": detectionProfile("Measles wastewater detection", "3", "Measles virus wastewater detection"),
  "Avian influenza A (H5)": detectionProfile("Avian influenza A (H5) wastewater detection", "2", "Avian influenza A (H5) wastewater detection"),
  "Mpox": detectionProfile("Mpox wastewater detection", "1", "Mpox virus wastewater detection"),
  "Influenza B": validationProfile("Influenza B"),
  "Norovirus": validationProfile("Norovirus"),
  "Enterovirus D68": validationProfile("Enterovirus D68"),
  "Poliovirus": validationProfile("Poliovirus"),
  "Adenovirus": validationProfile("Adenovirus"),
  "Candida auris": validationProfile("Candida auris"),
  "Antimicrobial resistance markers": validationProfile("Antimicrobial resistance markers")
};
const dataset = {
  "Wastewater concentration": { title: "Wastewater concentration", unit: "Weekly median · copies per milliliter", color: "#c8461f", path: "M0,206 L69,193 L138,199 L207,177 L276,183 L345,163 L414,171 L483,143 L552,150 L621,115 L690,76 L760,58", points: [[0,206],[69,193],[138,199],[207,177],[276,183],[345,163],[414,171],[483,143],[552,150],[621,115],[690,76],[760,58]], y: ["1,000","750","500","250","0"], observation: "recent measurements are higher than the prior 7-day period" },
  "Test positivity": { title: "Test positivity", unit: "Weekly share of reported tests · percent", color: "#b22d2d", path: "M0,174 L69,182 L138,165 L207,183 L276,160 L345,153 L414,157 L483,138 L552,145 L621,123 L690,104 L760,93", points: [[0,174],[69,182],[138,165],[207,183],[276,160],[345,153],[414,157],[483,138],[552,145],[621,123],[690,104],[760,93]], y: ["8%","6%","4%","2%","0%"], observation: "reported positivity is above the prior reporting week" },
  "Hospital admissions": { title: "Hospital admissions", unit: "Weekly rate · admissions per 100,000 residents", color: "#177d79", path: "M0,99 L69,105 L138,111 L207,105 L276,119 L345,128 L414,121 L483,139 L552,133 L621,145 L690,151 L760,158", points: [[0,99],[69,105],[138,111],[207,105],[276,119],[345,128],[414,121],[483,139],[552,133],[621,145],[690,151],[760,158]], y: ["40","30","20","10","0"], observation: "the reported admission rate is lower than the prior reporting week" }
};
let current = "Wastewater concentration";
const modal = $("#modal"), backdrop = $("#modalBackdrop"), modalContent = $("#modalContent");
function currentPathogenProfile() { return pathogenProfiles[$("#pathogenSelect").value] || pathogenProfiles["COVID-19"]; }
function displayIndicatorTitle(indicator) { return indicator === "Wastewater concentration" ? currentPathogenProfile().title : dataset[indicator].title; }
function applyPathogenContext() { const profile = currentPathogenProfile(), trend = $("#wastewaterTrend"); $("#wastewaterMetricTitle").textContent = profile.title; $("#wastewaterMetricValue").textContent = profile.value; $("#wastewaterMetricUnit").textContent = profile.unit; trend.className = `metric-trend ${profile.mode === "validation" ? "pending" : "up"}`; trend.innerHTML = `${profile.trend} <span>${profile.trendNote}</span>`; $("#wastewaterCoverage").innerHTML = profile.coverage; $("#pathogenMode").textContent = profile.modeLabel; $("#pathogenModeCopy").textContent = profile.modeCopy; $("#pathogenNotice").className = `context-status pathogen-notice ${profile.mode}`; if (current === "Wastewater concentration") updateChart(current); }
function openModal(title, html) { modalContent.innerHTML = `<h2 class="modal-title">${title}</h2><div class="modal-copy">${html}</div>`; backdrop.hidden = false; modal.showModal(); }
function closeModal() { modal.close(); backdrop.hidden = true; }
function toast(message) { const el = $("#toast"); el.textContent = message; el.classList.add("show"); setTimeout(() => el.classList.remove("show"), 2600); }
function updateChart(indicator) {
  current = indicator; const item = dataset[indicator];
  const profile = indicator === "Wastewater concentration" ? currentPathogenProfile() : null;
  $("#chartHeading").textContent = profile ? profile.title : item.title; $("#chartSubline").textContent = profile ? profile.chartUnit : item.unit;
  $("#linePath").setAttribute("d", item.path); $("#linePath").setAttribute("stroke", item.color);
  $("#areaPath").setAttribute("d", `${item.path} L760,240 L0,240 Z`);
  $("#areaPath").setAttribute("fill", "url(#areaGradient)");
  $("#dataPoints").innerHTML = item.points.map(([cx,cy]) => `<circle cx="${cx}" cy="${cy}" r="4"/>`).join("");
  $("#dataPoints").setAttribute("stroke", item.color);
  $$(".y-axis span").forEach((el, i) => el.textContent = (profile ? profile.y : item.y)[i]);
  const unavailable = Boolean(profile && profile.mode === "validation"); $("#chartUnavailable").hidden = !unavailable; $(".chart-wrap").classList.toggle("is-unavailable", unavailable); $(".chart-legend").classList.toggle("is-unavailable", unavailable);
  $(".chart-callout p").innerHTML = unavailable ? `<b>State comparison unavailable</b><span>Public coverage and comparison methods must be validated before this pathogen can be shown at state level.</span>` : `<b>Observed change</b><span>${item.observation}. This is not a statement about transmission, severity, or what will happen next.</span>`;
  $$(".metric-card").forEach(card => card.classList.toggle("selected", card.dataset.indicator === indicator));
}
function showView(id) { $$(".view").forEach(v => v.classList.toggle("active", v.id === id)); $$(".nav-item").forEach(b => b.classList.toggle("active", b.dataset.view === id)); const title = {dashboard:"Regional dashboard",explore:"Data explorer",sources:"Sources & quality",lab:"Early warning lab",plans:"Preparedness plans"}[id]; $("#crumbTitle").textContent = title; window.scrollTo({top:0,behavior:"smooth"}); }
$$('.nav-item').forEach(btn => btn.addEventListener('click', () => showView(btn.dataset.view)));
$$('[data-go]').forEach(btn => btn.addEventListener('click', () => showView(btn.dataset.go)));
$$('.metric-card').forEach(card => card.addEventListener('click', () => updateChart(card.dataset.indicator)));
$("#regionSelect").addEventListener("change", e => { $("#regionTitle").textContent = e.target.value; toast(`Showing illustrative observations for ${e.target.value}`); });
$("#pathogenSelect").addEventListener("change", e => { applyPathogenContext(); toast(`Pathogen context set to ${e.target.value}`); });
$("#periodSelect").addEventListener("change", e => toast(`Time period updated to ${e.target.value}`));
$$('.range').forEach(b => b.addEventListener('click', () => { $$('.range').forEach(x=>x.classList.remove('active')); b.classList.add('active'); toast(`${b.textContent} display range selected`); }));
$("#interpretationButton").addEventListener("click", () => openModal("How to read this dashboard", `<p><strong>Observed</strong> means a source reported a measurement. It does not establish why it changed or what will happen next.</p><ul><li>Compare values only when the unit and reporting period are compatible.</li><li>Check age, coverage, and method before interpreting an apparent change.</li><li>Forecasts, when available, will use distinct labels.</li></ul>`));
$("#qualityButton").addEventListener("click", () => openModal("Quality notes", `<p class="modal-label">WASTEWATER ACTIVITY</p><p><strong>Coverage:</strong> 9 of 12 example sites contributed to the latest aggregate.</p><p><strong>Comparability:</strong> wastewater activity and clinical indicators measure different processes and must not be treated as equivalent values.</p><p><strong>Freshness:</strong> the latest snapshot was retrieved two hours ago in this demonstration.</p>`));
$("#metadataButton").addEventListener("click", () => { const profile = currentPathogenProfile(); openModal("Dataset metadata", `<p><strong>Provider:</strong> Illustrative national & state surveillance dataset</p><p><strong>Indicator:</strong> ${profile.metadata}</p><p><strong>Aggregation:</strong> weekly standardized activity across available reporting areas</p><p><strong>Retrieval:</strong> November 13, 2026, 09:30 ET</p><p><strong>Prototype note:</strong> all values and dates in this build are synthetic UI data.</p>`); });
$("#sourceLink").addEventListener("click", () => showView("sources"));
$("#compareButton").addEventListener("click", () => { showView("explore"); });
$("#runCompare").addEventListener("click", () => { const primary = $("#primaryRegionSelect").value, secondary = $("#secondaryRegionSelect").value; ["#comparisonPrimary", "#comparisonPrimaryLegend"].forEach(selector => $(selector).textContent = primary); ["#comparisonSecondary", "#comparisonSecondaryLegend"].forEach(selector => $(selector).textContent = secondary); toast("Illustrative comparison updated"); });
$("#aboutButton").addEventListener("click", () => openModal("About SpreadSignal", `<p>A modular, pathogen-agnostic workspace for moving from <strong>observation</strong> to <strong>exploration</strong> to proportionate, human-directed planning.</p><p>This interactive prototype focuses on the MVP dashboard, geographic selection, historical observations, comparison constraints, and provenance.</p>`));
$("#closeModal").addEventListener("click", closeModal); backdrop.addEventListener("click", closeModal);
$("#exportButton").addEventListener("click", () => { const profile = current === "Wastewater concentration" ? currentPathogenProfile() : null, unit = profile ? profile.unit : dataset[current].unit; const rows = ["indicator,value,unit,region,period,source,retrieved_at",`\"${displayIndicatorTitle(current)}\",illustrative,\"${unit}\",\"${$("#regionSelect").value}\",\"Last 12 weeks\",\"Synthetic prototype data\",\"2026-11-13T09:30:00-05:00\"`]; const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([rows.join("\n")], {type:"text/csv"})); a.download = "spreadsignal-prototype-export.csv"; a.click(); URL.revokeObjectURL(a.href); toast("CSV exported with source context"); });
$$('.definition').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); openModal("Indicator definition", `<p><strong>${displayIndicatorTitle(current)}</strong></p><p>This is a simplified prototype definition. In production, the indicator definition would include its measurement method, aggregation, unit, compatible comparisons, provider, and limitations.</p>`); }));
const lagData = {0:{r:"0.28",title:"Modest alignment at 0 days",copy:"The selected synthetic series move together somewhat in the same reporting week. This does not establish a relationship."},7:{r:"0.71",title:"Highest observed alignment at 7 days",copy:"In this synthetic example, the leading series rises before the following series. The sample is too limited to support a conclusion."},14:{r:"0.49",title:"Moderate alignment at 14 days",copy:"A pattern remains visible after two weeks, but it is weaker in this small synthetic sample."},21:{r:"0.19",title:"Weak alignment at 21 days",copy:"Little alignment is visible at this offset in the selected synthetic observations."}};
function setLag(lag) { const value = lagData[lag]; $("#lagRange").value = lag; $("#lagValue").textContent = `${lag} days`; $("#correlationValue").textContent = `r = ${value.r}`; $("#resultHeading").textContent = value.title; $("#resultCopy").textContent = value.copy; $$(".lag-bars button").forEach(b => b.classList.toggle("selected", Number(b.dataset.lag) === Number(lag))); }
function updateAnalysisTitle() { const lead = $("#leadSeries").selectedOptions[0].textContent.replace(" concentration",""); const follow = $("#followSeries").selectedOptions[0].textContent.replace("Hospital ",""); $("#analysisTitle").textContent = `${lead} → ${follow}`; }
$("#lagRange").addEventListener("input", e => setLag(Number(e.target.value)));
$$('.lag-bars button').forEach(b => b.addEventListener('click', () => setLag(Number(b.dataset.lag))));
$("#leadSeries").addEventListener("change", updateAnalysisTitle); $("#followSeries").addEventListener("change", updateAnalysisTitle);
$("#runAnalysis").addEventListener("click", () => { updateAnalysisTitle(); setLag(Number($("#lagRange").value)); toast("Exploratory analysis updated with synthetic data"); });
$("#labReset").addEventListener("click", () => { $("#leadSeries").value="wastewater"; $("#followSeries").value="admissions"; updateAnalysisTitle(); setLag(7); toast("Analysis reset to the demonstration example"); });
$("#methodButton").addEventListener("click", () => openModal("Analysis assumptions", `<p><strong>Input:</strong> 12 weekly synthetic values per series.</p><p><strong>Statistic:</strong> Pearson correlation after testing fixed 0-, 7-, 14-, and 21-day offsets.</p><p><strong>Limitations:</strong> correlation is exploratory; it cannot establish causation, account for confounding factors, or predict future outcomes.</p>`));
$("#ruleButton").addEventListener("click", () => openModal("Candidate anomaly rule", `<p>A candidate is marked when a weekly value is at least <strong>1.5 standard deviations</strong> from its trailing 8-week baseline, or when a source reports a material completeness change.</p><p>These are prompts for review, not confirmed events or alerts.</p>`));
$("#saveAnalysis").addEventListener("click", () => toast("Analysis saved locally as a synthetic-demo workspace"));
const thresholdLabels = {1:"One weekly increase",2:"Two consecutive weekly increases",3:"Three consecutive weekly increases"};
$("#thresholdRange").addEventListener("input", e => { $("#thresholdLabel").textContent = thresholdLabels[e.target.value]; });
function planValues() { return { org: $("#orgName").value.trim() || "Unnamed organization", owner: $("#planOwner").value.trim() || "No owner assigned", scenario: $("#scenarioSelect").value, threshold: $("#thresholdLabel").textContent, actions: $$(".action-option input:checked").map(x => x.value) }; }
$("#previewPlan").addEventListener("click", () => { const p = planValues(); const actions = p.actions.length ? `<ul>${p.actions.map(a => `<li>${a}</li>`).join("")}</ul>` : "<p>No preparedness actions selected.</p>"; openModal("Preparedness plan preview", `<p class="modal-label">DRAFT · HUMAN APPROVAL REQUIRED</p><p><strong>${p.org}</strong><br>${p.scenario}</p><p><strong>Review threshold:</strong> ${p.threshold}<br><strong>Plan owner:</strong> ${p.owner}</p><p><strong>Selected actions</strong></p>${actions}<p>This is an organizational planning aid, not medical advice or an automatic response trigger.</p>`); });
$("#approvePlan").addEventListener("click", () => { const p = planValues(); if (p.owner === "No owner assigned") { toast("Add a plan owner before marking the plan reviewed"); $("#planOwner").focus(); return; } const content = ["OUTBREAK INTELLIGENCE STUDIO — PREPAREDNESS PLAN", "", `Organization: ${p.org}`, `Scenario: ${p.scenario}`, `Review threshold: ${p.threshold}`, `Plan owner: ${p.owner}`, "Status: Human reviewed (prototype)", "", "Selected actions:", ...p.actions.map(a => `- ${a}`), "", "Note: This is a synthetic prototype plan. It is not medical advice and does not trigger actions automatically."].join("\n"); const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([content],{type:"text/plain"})); a.download="preparedness-plan.txt"; a.click(); URL.revokeObjectURL(a.href); $("#planStatus").textContent="Reviewed · export created"; $("#planSummary").textContent=`${p.owner} reviewed this prototype plan for ${p.org}.`; toast("Human-reviewed plan exported"); });
$("#loadPlan").addEventListener("click", () => { $("#orgName").value="Northside Community Center"; $("#planOwner").value="Operations director"; $("#scenarioSelect").value="Prepare for sustained indicator increase"; $("#thresholdRange").value=2; $("#thresholdLabel").textContent=thresholdLabels[2]; $$(".action-option input").forEach((x,i)=>x.checked=i<3); toast("Sample preparedness plan loaded"); });
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js", { updateViaCache: "none" }).catch(() => {});
